-- 将该建表 SQL 语句，添加到 yudao-module-oa-biz 模块的 test/resources/sql/create_tables.sql 文件里
CREATE TABLE IF NOT EXISTS "oa_sign_in_info" (
                                                 "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                                 "cover_pic_id" bigint,
                                                 "cover_pic_url" varchar,
                                                 "title" varchar,
                                                 "description" varchar,
                                                 "start_date" varchar,
                                                 "end_date" varchar,
                                                 "sign_in_time_type" varchar,
                                                 "person_info_need" bit,
                                                 "position_need" bit,
                                                 "position_info" varchar,
                                                 "scanner_need" bit,
                                                 "banner_id" bigint,
                                                 "banner_url" varchar,
                                                 "logo_id" bigint,
                                                 "logo_url" varchar,
                                                 "title_pic_url" varchar,
                                                 "title_pic_id" bigint,
                                                 "sign_task_count" int,
                                                 "creator" varchar DEFAULT '',
                                                 "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 "updater" varchar DEFAULT '',
                                                 "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                                 "deleted" bit NOT NULL DEFAULT FALSE,
                                                 "tenant_id" bigint NOT NULL,
                                                 PRIMARY KEY ("id")
) COMMENT '签到信息表';
